static void ns_head(int part) {
    if (part == 0) {
        for (int j = 0; j < 32; j++) ns_emb[j] = LC_FB0[j];
        for (int i = 0; i < 19; i++) for (int j = 0; j < 32; j++) ns_emb[j] += lc_vec[i] * LC_FW0[i * 32 + j];
        for (int j = 0; j < 32; j++) ns_emb[j] = ns_emb[j] > 0 ? ns_emb[j] : 0;
        for (int j = 0; j < 128; j++) ns_h[j] = LC_H1B[j];
        for (int i = 0; i < 6 * LC_C3; i++) { float a = lc_a3[i]; const float *w = LC_H1W + i * 128; for (int j = 0; j < 128; j++) ns_h[j] += a * w[j]; }
        return;
    }
    for (int i = 6 * LC_C3; i < 12 * LC_C3; i++) { float a = lc_a3[i]; const float *w = LC_H1W + i * 128; for (int j = 0; j < 128; j++) ns_h[j] += a * w[j]; }
    for (int i = 0; i < 32; i++) { float a = ns_emb[i]; const float *w = LC_H1W + (12 * LC_C3 + i) * 128; for (int j = 0; j < 128; j++) ns_h[j] += a * w[j]; }
    for (int j = 0; j < 128; j++) ns_h[j] = ns_h[j] > 0 ? ns_h[j] : 0;
    for (int j = 0; j < 12; j++) lc_out[j] = LC_H2B[j];
    for (int i = 0; i < 128; i++) { float a = ns_h[i]; const float *w = LC_H2W + i * 12; for (int j = 0; j < 12; j++) lc_out[j] += a * w[j]; }
}
static void lc_apply(void);
/* one micro-step; returns 0 if it cannot run yet */
#ifdef PROF
#define NSM(id) PM(id)
#else
#define NSM(id)
#endif
static int ns_do(int k) {
    NSM(k < 32 ? 27 : k < 56 ? 20 : k < 62 ? 26 : k < 74 ? 21 : k < 86 ? 22 : k < 92 ? 23 : k < 95 ? 24 : 25);
    if (k < 16) { for (int pr = 3 * k; pr < 3 * k + 3; pr++) lc_gray_pair(ns_rgb0, lc_g0, pr); return 1; }
    k -= 16;
    if (k < 16) { if (!ns_have5) return 0; for (int pr = 3 * k; pr < 3 * k + 3; pr++) lc_gray_pair(ns_rgb5, lc_g5, pr); return 1; }
    k -= 16;
    if (k < 24) { if (k == 0) ns_prep_init(); ns_prep_rows(4 * k, 4 * k + 4); return 1; }
    k -= 24;
    if (k < 4) { ns_var(k * (LC_H * LC_W / 4), (k + 1) * (LC_H * LC_W / 4)); return 1; }
    k -= 4;
    if (k < 2) { ns_pool(k * 24, k * 24 + 24); return 1; }
    k -= 2;
    if (k < 12) { ns_conv0(lc_in, lc_a0, 2 * k, 2 * k + 2); return 1; }
    k -= 12;
    if (k < 12) { ns_conv1(lc_a0, lc_a1, k, k + 1); return 1; }
    k -= 12;
    if (k < 6) { ns_conv2(lc_a1, lc_a2, k, k + 1); return 1; }
    k -= 6;
    if (k < 3) { ns_conv3(lc_a2, lc_a3, k, k + 1); return 1; }
    k -= 3;
    if (k == 0) { ns_head(0); return 1; }
    ns_head(1); lc_apply(); lc_next = 6; return 1;
}
